import json

from server.core import bibtex as bib
from server import refcheck_server as refcheck


def _canonical(authors, *, publication_type="article", venue="Journal"):
    return {
        "score": 1.0,
        "source": "openalex",
        "title": "A stable title",
        "authors": authors,
        "year": 2021,
        "venue": venue,
        "doi": None,
        "arxiv_id": None,
        "url": "https://openalex.org/W1",
        "publication_type": publication_type,
    }


def _fields(author, *, journal="Journal"):
    return {
        "title": "A stable title",
        "author": author,
        "year": "2021",
        "journal": journal,
    }


def test_same_person_normalises_last_first_on_both_sides():
    assert bib.same_person("Yashar Alizadeh", "Alizadeh, Yashar")
    assert bib.same_person("Alizadeh, Yashar", "Yashar Alizadeh")


def test_same_person_folds_unicode_confusable_initials_symmetrically():
    assert bib.same_person("M. J. Buerger", "Μ. J. Buerger")
    assert bib.same_person("Μ. J. Buerger", "M. J. Buerger")


def test_missing_authority_authors_are_not_called_a_mismatch(monkeypatch):
    monkeypatch.setattr(
        refcheck, "_authoritative_lookup",
        lambda fields: (_canonical([]), [], None),
    )
    result = refcheck._verify_fields(_fields("A. Author"))
    assert result["verdict"] == "UNVERIFIED"
    assert result["axes"]["authors"]["status"] == "UNVERIFIED"
    assert result["issues"][0]["type"] == "authority_missing"


def test_closed_evidence_backed_adjudication_fills_missing_author_axis(monkeypatch):
    monkeypatch.setattr(
        refcheck, "_authoritative_lookup",
        lambda fields: (_canonical([]), [], None),
    )
    result = refcheck._verify_fields(_fields("A. N. Christensen"), {
        "status": "PASS",
        "closed": True,
        "canonical_authors": ["A. Nørlund Christensen"],
        "evidence": "Authority record 1",
    })
    assert result["verdict"] == "PASS"
    assert result["axes"]["authors"]["basis"] == "closed_serial_adjudication"


def test_closed_adjudication_rejects_polluted_canonical_authors(monkeypatch):
    polluted = ["Example University, Department", "Salih Emre Yıldırım",
                "Adviser Doctor Example"]
    monkeypatch.setattr(
        refcheck, "_authoritative_lookup",
        lambda fields: (_canonical(polluted, publication_type="dissertation",
                                   venue="Repository Host"), [], None),
    )
    result = refcheck._verify_fields(
        _fields("Salih Emre Yıldırım", journal="University Institute"),
        {
            "status": "PASS",
            "closed": True,
            "canonical_authors": ["Yıldırım, Salih Emre"],
            "evidence": "Institutional repository full record",
        },
    )
    assert result["verdict"] == "PASS"
    assert result["axes"]["authors"]["canonical_raw"] == polluted


def test_verify_bib_file_preserves_and_uses_generic_serial_adjudication(
        monkeypatch, tmp_path):
    bib_path = tmp_path / "refs.bib"
    bib_path.write_text(
        "@article{generic, author={A. Author}, title={A stable title}, "
        "year={2021}, journal={Journal}}",
        encoding="utf-8",
    )
    audit_path = tmp_path / "CITATION_AUDIT.json"
    serial = {
        "authority_axes": {
            "generic": {
                "author_adjudication": {
                    "status": "PASS",
                    "closed": True,
                    "canonical_authors": ["A. Author"],
                    "evidence": "Authority record 2",
                }
            }
        }
    }
    audit_path.write_text(json.dumps({"serial_adjudication": serial}), encoding="utf-8")
    monkeypatch.setattr(
        refcheck, "_authoritative_lookup",
        lambda fields: (_canonical([]), [], None),
    )

    result = json.loads(refcheck.verify_bib_file(str(bib_path), str(tmp_path)))
    audit = json.loads(audit_path.read_text(encoding="utf-8"))

    assert result["gate"] == "PASS"
    assert result["counts"]["PASS"] == 1
    assert audit["serial_adjudication"] == serial
